void Apply_Mic_Correction(float32_t* mag_buffer, float sample_rate, int fft_length) {
    float bin_width = sample_rate / (float)fft_length;
    int table_idx = 0;

    // We only need to correct up to ~2kHz (or Nyquist). 
    // Optimization: Don't iterate past the table's max freq.
    int max_bin = (int)(12000.0f / bin_width); 
    if (max_bin > fft_length/2) max_bin = fft_length/2;

    for (int i = 1; i < max_bin; i++) {
        float current_freq = (float)i * bin_width;

        // Advance the table index if we passed the current point
        while (table_idx < TABLE_SIZE - 1 && current_freq > MIC_RESPONSE[table_idx+1].freq) {
            table_idx++;
        }

        // Linear Interpolation
        CorrectionPoint p1 = MIC_RESPONSE[table_idx];
        CorrectionPoint p2 = MIC_RESPONSE[table_idx+1];
        
        float slope = (p2.gain - p1.gain) / (p2.freq - p1.freq);
        float gain = p1.gain + slope * (current_freq - p1.freq);

        // Apply gain
        mag_buffer[i] *= gain;
    }
}
