void Get_Note_Name(float freq, char* output_buffer, int* midi_note) {
    // 1. Handle Silence / Noise
    if (freq < 20.0f || freq > 4200.0f) {
        sprintf(output_buffer, "---");
        *midi_note = -1;
        sprintf(output_buffer, "Z0");
        return;
    }

    // 2. Calculate MIDI Note Number
    // Formula: n = 12 * log2(freq / 440) + 69
    // We use log(x) / log(2) because standard C might not have log2f optimized
    float note_num_float = 12.0f * (logf(freq / 440.0f) / logf(2.0f)) + 69.0f;
    
    // 3. Round to nearest integer (Standard Rounding)
    int note_num = (int)(note_num_float + 0.5f);
    *midi_note = note_num;
    

    // 4. Calculate Octave and Note Index
    // MIDI 0 is C-1. MIDI 12 is C0. MIDI 60 is C4 (Middle C).
    int octave = (note_num / 12) - 1;
    int note_index = note_num % 12;

    // 5. Handle bounds (Optional safety)
    if (note_index < 0) note_index = 0; // Prevent negative array index
    
    // 6. Write to buffer (e.g., "C" + "4" = "C4")
    sprintf(output_buffer, "%s%d", NOTE_NAMES[note_index], octave);

}

void Send_Data_To_PC(float32_t* data_array, int length, int save_number) {
    char msg_buffer[64]; // Temporary buffer for one line of text
    int len;

    // 1. Header
    len = sprintf(msg_buffer, "\r\n\r\n=== BATCH %d ===\r\n", save_number);
    CDC_Transmit_FS((uint8_t*)msg_buffer, len);
    HAL_Delay(5); // Small delay to let USB flush

    // 2. The Loop
    for (int i = 0; i < length; i++) {
        // Format: "Index, Value" (CSV friendly)
        len = sprintf(msg_buffer, "%d, %.2f\r\n", i, data_array[i]);
        
        // Send it
        uint8_t result = CDC_Transmit_FS((uint8_t*)msg_buffer, len);
        
        // SAFETY: If USB is busy, wait a tiny bit and retry (simple blocking)
        // STM32 USB buffers are small; sending 2048 lines instantly will overflow them.
        HAL_Delay(2); 
    }

    // 3. Footer
    len = sprintf(msg_buffer, "=== END ===\r\n");
    CDC_Transmit_FS((uint8_t*)msg_buffer, len);
}

/**
 * @brief  YIN Pitch Detection Algorithm
 * @param  input_buffer: Your audio samples (Must be centered at 0, float)
 * @param  buffer_len: Length of input_buffer (e.g., 2048 or 4096)
 * @param  sample_rate: Your Sampling Rate (e.g., 12000)
 * @return Frequency in Hz, or -1.0 if no pitch found
 */
void YIN_GetPitch(float* input_buffer, int buffer_len, int sample_rate, float32_t* output_array) {
    int tau, j;
    
    // We can only check for periods up to half the buffer length
    // For 12kHz, buffer 2048 -> Max Period 1024 samples (approx 11 Hz limit). Plenty.
    int max_tau = buffer_len / 2;
    
    // Safety clamp to prevent buffer overflow
    if (max_tau > YIN_BUFFER_SIZE) max_tau = YIN_BUFFER_SIZE;

    // ==============================================================================
    // STEP 1: Optimized Difference Function (CMSIS-DSP)
    // Formula: d(tau) = Energy_Fixed + Energy_Sliding - 2 * Correlation(tau)
    // ==============================================================================

    // 1. Calculate the energy of the first window (Fixed Term)
    // We sum the squares of the first 'max_tau' samples.
    float fixed_energy = 0.0f;
    arm_dot_prod_f32(input_buffer, input_buffer, max_tau, &fixed_energy);

    // 2. Initialize the Sliding Energy (starts equal to fixed energy at tau=0)
    float sliding_energy = fixed_energy;

    int candidates[numb_notes/2];
    float candidate_values[numb_notes/2];

    // 3. The Main Loop
    for (tau = 0; tau < max_tau; tau++) {
        // A. Calculate Correlation (The heavy lifting)
        // using the DSP-optimized dot product function
        float correlation = 0.0f;
        arm_dot_prod_f32(&input_buffer[0], &input_buffer[tau], max_tau, &correlation);

        // B. Apply the Difference Formula
        yin_buffer[tau] = fixed_energy + sliding_energy - (2.0f * correlation);

        // C. Efficiently update the Sliding Energy for the NEXT iteration
        // Instead of re-calculating the whole sum, we just subtract the old sample 
        // that slid out and add the new sample that slid in.
        float sample_out = input_buffer[tau];
        float sample_in  = input_buffer[tau + max_tau];
        
        sliding_energy = sliding_energy - (sample_out * sample_out) + (sample_in * sample_in);
    }

    // ==============================================================================
    // STEP 2: Cumulative Mean Normalized Difference Function (CMNDF)
    // "Normalize the dip so it starts at 1.0 and drops."
    // This fixes the issue where Zero-Lag is always 0.
    // ==============================================================================
    yin_buffer[0] = 1.0f;
    float running_sum = 0.0f;
    
    for (tau = 1; tau < max_tau; tau++) {
        running_sum += yin_buffer[tau];
        
        // Formula: d'(t) = d(t) * t / sum(d[1]...d[t])
        // If running_sum is 0, we avoid div by zero
        if (running_sum == 0.0f) {
            yin_buffer[tau] = 1.0f;
        } else {
            yin_buffer[tau] *= (float)tau / running_sum;
        }
    }

    // ==============================================================================
    // STEP 3: Absolute Threshold Search
    // "Find the first valley that dips below the threshold."
    // This prevents the "Octave Error" (picking a period that is too long).
    // ==============================================================================
    int best_tau = -1;
    
    // Start at tau=2 to avoid high-frequency noise at index 0/1
    int num_candidates = 0;
    for (tau = 2; tau < max_tau; tau++) {
      if (yin_buffer[tau] < YIN_THRESHOLD) {
          // Find the local minimum in this valley
          while (tau + 1 < max_tau && yin_buffer[tau + 1] < yin_buffer[tau]) {
              tau++;
          }
          // Record this candidate (if we have space)
          if (num_candidates < (int)numb_notes/2) {
              candidates[num_candidates] = tau;
              candidate_values[num_candidates] = yin_buffer[tau];
              num_candidates++;
          }
          tau++;
          // Continue searching for the next valley, not break
      }
    }

    // Fallback: If no dip is deep enough (noisy signal), find the global minimum
    // Note: You might want to return -1 here instead to indicate "Unpitched Noise"

    // ==============================================================================
    // STEP 4: Parabolic Interpolation
    // "Refine the integer index to a decimal for higher accuracy."
    // ==============================================================================
    if (num_candidates == 0) {
        for(int i = 0; i < numb_notes/2; i++) {
            output_array[i] = 0.0f;
        }
        return;
    }
    for (int i = 0; i<((int)numb_notes/2); i++) {
      
      best_tau = candidates[i];
      float refined_tau = (float)best_tau;
    
      if (best_tau > 0 && best_tau < max_tau - 1) {
          float s0 = yin_buffer[best_tau - 1];
          float s1 = yin_buffer[best_tau];
          float s2 = yin_buffer[best_tau + 1];
          
          // Parabolic peak location formula
          float adjustment = (s2 - s0) / (2.0f * (2.0f * s1 - s2 - s0));
          refined_tau += adjustment;
      }
      output_array[i] = (float32_t)sample_rate / refined_tau;
    }
    

    // ==============================================================================
    // STEP 5: Convert Period to Frequency
    // ==============================================================================
    //float pitch_in_hz = (float)sample_rate / refined_tau;
}


